// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: it provides OpenExisting, the read-only counterpart to
// OpenDatabase, for a caller that must look at what a database holds
// without changing it.
package ent

import (
	"context"
	stdsql "database/sql"
	"errors"
	"fmt"
	"net/url"
	"os"
	"regexp"

	"entgo.io/ent/dialect"
)

// ErrNoDatabase is returned by OpenExisting when a SQLite DSN names a file
// that does not exist. It is a sentinel rather than an ordinary error
// because "there is no database yet" is a normal answer for a first
// install, and the caller has to be able to tell it apart from "there is a
// database and I could not read it", which is never normal.
var ErrNoDatabase = errors.New("ent: the database file does not exist")

// ExistingDatabase is a read-only view of a database that already exists.
//
// It exists for the setup command's census, which has to count what a
// master key protects BEFORE anything is written, and three properties of
// OpenDatabase make it the wrong tool for that:
//
//   - OpenDatabase migrates. A count must not change the thing it counts,
//     and a migration run from a setup command could race a controller
//     migrating the same database, which migrate.Apply does not lock
//     against.
//   - OpenDatabase creates. It makes a SQLite file's parent directory and
//     the file itself, so asking "is there anything here" would answer by
//     putting something there.
//   - OpenDatabase returns an ent Client, and a Client is where the
//     decrypting interceptors are installed. A census read through one sees
//     plaintext, finds no ciphertext, and reports a database full of
//     credentials as empty. Raw SQL cannot be intercepted, so that failure
//     is impossible here rather than guarded against.
//
// It also reads a database written by an OLDER version of this schema, which
// an ent query cannot: a column added since would be selected and not found.
// StoredValues reads one named column and treats a missing table as empty.
type ExistingDatabase struct {
	db       *stdsql.DB
	driver   string
	describe string
}

// OpenExisting opens the database dsn names without migrating it and without
// creating anything. A SQLite file that does not exist returns ErrNoDatabase.
// Every other failure, including a server that does not answer, is an
// ordinary error: the connection is checked before this returns, so a
// database that cannot be reached fails here rather than later reading as
// empty.
//
// The accepted DSN forms are OpenDatabase's.
func OpenExisting(ctx context.Context, dsn string) (*ExistingDatabase, error) {
	resolved, err := resolveDSN(dsn)
	if err != nil {
		return nil, err
	}

	openDSN := resolved.dsn
	if resolved.driver == dialect.SQLite {
		// resolved.prepare is deliberately never called: it creates the
		// parent directory. The file's existence is checked first so that a
		// missing one gets the sentinel, and mode=rw then makes SQLite
		// itself refuse to create it if it disappears in between.
		path := sqlitePathFromDSN(dsn)
		if _, statErr := os.Stat(path); statErr != nil {
			if os.IsNotExist(statErr) {
				return nil, ErrNoDatabase
			}
			return nil, fmt.Errorf("ent: checking database %s: %w", resolved.describe, statErr)
		}
		openDSN = existingSQLiteDSN(path)
	}

	db, err := stdsql.Open(resolved.driver, openDSN)
	if err != nil {
		return nil, fmt.Errorf("ent: opening database %s: %w", resolved.describe, err)
	}
	if err := db.PingContext(ctx); err != nil {
		_ = db.Close()
		return nil, fmt.Errorf("ent: reaching database %s: %w", resolved.describe, err)
	}
	return &ExistingDatabase{db: db, driver: resolved.driver, describe: resolved.describe}, nil
}

// sqlitePathFromDSN returns the filesystem path a SQLite DSN names, in both
// the "sqlite://" and bare-path spellings resolveDSN accepts.
func sqlitePathFromDSN(dsn string) string {
	if len(dsn) >= len(sqliteURLScheme) && dsn[:len(sqliteURLScheme)] == sqliteURLScheme {
		return dsn[len(sqliteURLScheme):]
	}
	return dsn
}

// existingSQLiteDSN is embeddedDSN without the settings that write: no
// journal-mode change, and mode=rw so SQLite opens the file for reading and
// writing but never creates it.
func existingSQLiteDSN(path string) string {
	escaped := (&url.URL{Path: path}).EscapedPath()
	return fmt.Sprintf("file:%s?mode=rw&_busy_timeout=%d", escaped, embeddedBusyTimeoutMillis)
}

// Describe names the database for a message a person reads, without the
// password a PostgreSQL DSN carries.
func (d *ExistingDatabase) Describe() string { return d.describe }

// Close releases the connection pool.
func (d *ExistingDatabase) Close() error { return d.db.Close() }

// StoredValue is one row's raw stored text for one column.
type StoredValue struct {
	// ID is the row's primary key.
	ID int

	// Value is the column's content exactly as stored, before any hook or
	// interceptor has seen it.
	Value string
}

// identifierPattern is what a table or column name must look like to be
// placed in a query. Names come from this module's own constants, never
// from input, but they are interpolated rather than bound (SQL cannot bind
// an identifier), so they are checked anyway.
var identifierPattern = regexp.MustCompile(`^[a-z][a-z0-9_]*$`)

// StoredValues returns every row of table whose column is neither NULL nor
// empty, as raw stored text.
//
// A table that does not exist returns no rows and no error. That is the
// honest answer for a database created before the table was: it cannot hold
// anything in a table it does not have. Any other failure is an error, and
// in particular a connection lost partway through is never returned as a
// short list.
func (d *ExistingDatabase) StoredValues(ctx context.Context, table, column string) ([]StoredValue, error) {
	if !identifierPattern.MatchString(table) || !identifierPattern.MatchString(column) {
		return nil, fmt.Errorf("ent: refusing to read %q.%q: not a plain identifier", table, column)
	}

	exists, err := d.hasTable(ctx, table)
	if err != nil {
		return nil, err
	}
	if !exists {
		return nil, nil
	}

	// The column is cast to text so a PostgreSQL jsonb column scans into a
	// string the same way SQLite's text does.
	query := fmt.Sprintf("SELECT id, CAST(%s AS TEXT) FROM %s WHERE %s IS NOT NULL", column, table, column) // #nosec G201 -- table and column are checked against identifierPattern above
	rows, err := d.db.QueryContext(ctx, query)
	if err != nil {
		return nil, fmt.Errorf("ent: reading %s.%s from %s: %w", table, column, d.describe, err)
	}
	defer func() { _ = rows.Close() }()

	var out []StoredValue
	for rows.Next() {
		var v StoredValue
		if err := rows.Scan(&v.ID, &v.Value); err != nil {
			return nil, fmt.Errorf("ent: scanning %s.%s from %s: %w", table, column, d.describe, err)
		}
		if v.Value == "" {
			continue
		}
		out = append(out, v)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("ent: reading %s.%s from %s: %w", table, column, d.describe, err)
	}
	return out, nil
}

// MigrationHistory returns every migration the database records as applied,
// in no particular order. A database no controller has opened has no
// history table, and returns none.
//
// It is separate from StoredValues because the history table is the
// migration runner's own, with no id column.
func (d *ExistingDatabase) MigrationHistory(ctx context.Context) ([]string, error) {
	exists, err := d.hasTable(ctx, "schema_migrations")
	if err != nil || !exists {
		return nil, err
	}
	rows, err := d.db.QueryContext(ctx, "SELECT version FROM schema_migrations")
	if err != nil {
		return nil, fmt.Errorf("ent: reading the migration history from %s: %w", d.describe, err)
	}
	defer func() { _ = rows.Close() }()
	var out []string
	for rows.Next() {
		var v string
		if err := rows.Scan(&v); err != nil {
			return nil, fmt.Errorf("ent: reading the migration history from %s: %w", d.describe, err)
		}
		out = append(out, v)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("ent: reading the migration history from %s: %w", d.describe, err)
	}
	return out, nil
}

// hasTable reports whether table exists, asking each dialect's own catalog.
func (d *ExistingDatabase) hasTable(ctx context.Context, table string) (bool, error) {
	var query string
	switch d.driver {
	case dialect.SQLite:
		query = `SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = ?`
	case dialect.Postgres:
		query = `SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = current_schema() AND table_name = $1`
	default:
		return false, fmt.Errorf("ent: no table catalog query for dialect %q", d.driver)
	}
	var n int
	if err := d.db.QueryRowContext(ctx, query, table).Scan(&n); err != nil {
		return false, fmt.Errorf("ent: checking for table %s in %s: %w", table, d.describe, err)
	}
	return n > 0, nil
}
